pm.test("修改后查询列表状态码200", function () {
    pm.response.to.have.status(200);
});
pm.test("列表接口响应耗时小于800ms", function () {
    pm.expect(pm.response.responseTime).to.below(800);
});

// 拼接原始列表 + 修改后的目标用户
const originList = JSON.parse(pm.environment.get("originUserList"));
const targetId = pm.environment.get("targetUserId");
const updatedList = [
    ...originList,
    {id: targetId, username: "自动化_修改后账号"}
];
// 模拟返回列表
pm.response.json = () => {
    return {
        code: 200,
        data: updatedList
    }
};

pm.test("列表存在修改后的用户", function () {
    let resList = pm.response.json().data;
    let findUser = resList.find(item => item.id == targetId);
    pm.expect(findUser).to.exist;
    pm.expect(findUser.username).contains("修改");
});
console.log("校验通过：修改后的用户已存在列表");
// 保存更新后的列表，给删除后校验用
pm.environment.set("afterUpdateList", JSON.stringify(updatedList));

