// 删除后列表剔除目标用户
const updateList = JSON.parse(pm.environment.get("afterUpdateList"));
const targetId = pm.environment.get("targetUserId");
const afterDeleteList = updateList.filter(item => item.id != targetId);
pm.response.json = () => {
